079,-0.814649],[40.234983,-0.814728],[40.23491,-0.814795],[40.234875,-0.814881],[40.234821,-0.814941],[40.234745,-0.814913],[40.23464,-0.81489],[40.234507,-0.814893],[40.234374,-0.814954],[40.234275,-0.81504],[40.234231,-0.815125],[40.234202,-0.815278],[40.234202,-0.815411],[40.234177,-0.81549],[40.234091,-0.815535],[40.234018,-0.81551],[40.233958,-0.815427],[40.233923,-0.815319],[40.233862,-0.815208],[40.233796,-0.815119],[40.233697,-0.815059],[40.233564,-0.815024],[40.233434,-0.81497],[40.233332,-0.814929],[40.23324,-0.814887],[40.233088,-0.814827],[40.233015,-0.814789],[40.232964,-0.814725],[40.232954,-0.814662],[40.232926,-0.814624],[40.232811,-0.814627],[40.232713,-0.81463],[40.232576,-0.814633],[40.232437,-0.814636],[40.232386,-0.814678],[40.232376,-0.814817],[40.232361,-0.815005],[40.232364,-0.815154],[40.232354,-0.815221],[40.232278,-0.815236],[40.232227,-0.815202],[40.232192,-0.815059],[40.23217,-0.814938],[40.232106,-0.814795],[40.23203,-0.814722],[40.231887,-0.814709],[40.231808,-0.814706],[40.231694,-0.814738],[40.231614,-0.814789],[40.231529,-0.814789],[40.231392,-0.814786],[40.231303,-0.814709],[40.231198,-0.814614],[40.231119,-0.814563],[40.23102,-0.814503],[40.230925,-0.814494],[40.23077,-0.814509],[40.230671,-0.8145],[40.230535,-0.814494],[40.230382,-0.81449],[40.230239,-0.814468],[40.230119,-0.814389],[40.230027,-0.814297],[40.229896,-0.814151],[40.229747,-0.814052],[40.229592,-0.813947],[40.229328,-0.813779],[40.229172,-0.813646],[40.229074,-0.813528],[40.228836,-0.813408],[40.22869,-0.8133],[40.22855,-0.813204],[40.228398,-0.813314]],"expected_name":"Senda del Maestrazgo - Etapa 14"}]'::jsonb;
  v_source jsonb;
  v_route record;
  v_points jsonb;
  v_count integer;
  v_length_km double precision;
  v_max_gap_km double precision;
  v_center_gap_km double precision;
  v_invalid integer;
  v_id text;
begin
  for v_source in select value from jsonb_array_elements(v_sources) as x(value) loop
    v_id := v_source->>'route_id';
    select h.id,h.name,h.official_url,h.distance_km,h.latitude,h.longitude,t.status
      into v_route from public.hiking_routes h
      left join public.hiking_route_tracks t on t.route_id=h.id
      where h.id=v_id and h.source='openstreetmap'
        and exists (select 1 from public.hiking_route_regions m
          where m.route_id=h.id and m.published);
    if not found then raise exception 'Eligible route not found: %',v_id; end if;
    if v_route.status='ready' then continue; end if;
    if v_route.name<>v_source->>'expected_name' or
       v_route.official_url not in (v_source->>'page_url',
         'https://senderosturisticos.turismodearagon.com/senderos/gr8') then
      raise exception 'Official route identity mismatch: %',v_id;
    end if;
    with points as (
      select ordinality idx,(point->>0)::double precision lat,
        (point->>1)::double precision lon
      from jsonb_array_elements(v_source->'coords')
        with ordinality as p(point,ordinality)
    ), steps as (
      select lat,lon,lag(lat) over(order by idx) prev_lat,
        lag(lon) over(order by idx) prev_lon from points
    ), distances as (
      select case when prev_lat is null then 0 else 6371*2*asin(sqrt(
        least(1,power(sin(radians(lat-prev_lat)/2),2)+
        cos(radians(prev_lat))*cos(radians(lat))*
        power(sin(radians(lon-prev_lon)/2),2)))) end step_km,
        6371*2*asin(sqrt(least(1,
          power(sin(radians(lat-v_route.latitude)/2),2)+
          cos(radians(v_route.latitude))*cos(radians(lat))*
          power(sin(radians(lon-v_route.longitude)/2),2)))) center_km,
        (lat between 27 and 45 and lon between -19 and 5) valid from steps
    )
    select count(*),coalesce(sum(step_km),0),coalesce(max(step_km),0),
      coalesce(min(center_km),999),count(*) filter(where not valid)
      into v_count,v_length_km,v_max_gap_km,v_center_gap_km,v_invalid
      from distances;
    if v_count<>(v_source->>'expected_points')::integer or v_count<100
      or v_invalid>0 or v_length_km<=0 or v_max_gap_km>0.3
      or v_center_gap_km>3
      or abs(v_length_km/(v_source->>'official_km')::double precision-1)>0.08
      or (v_route.distance_km is not null and
          abs(v_length_km/v_route.distance_km::double precision-1)>0.08) then
      raise exception 'Aragon track validation failed for %: %, %, %, %, %',
        v_id,v_count,v_length_km,v_max_gap_km,v_center_gap_km,v_invalid;
    end if;
    select jsonb_agg(jsonb_build_object('lat',(point->>0)::double precision,
      'lon',(point->>1)::double precision) order by ordinality)
      into v_points from jsonb_array_elements(v_source->'coords')
        with ordinality as p(point,ordinality);
    insert into public.hiking_route_tracks
      (route_id,status,segments,checked_at,continuity_checked,
       geometry_source,geometry_source_url,official)
    values (v_id,'ready',jsonb_build_array(v_points),now(),true,
      'Senderos Turísticos de Aragón',v_source->>'gpx_url',true)
    on conflict(route_id) do update set
      status=excluded.status,segments=excluded.segments,
      checked_at=excluded.checked_at,continuity_checked=true,
      geometry_source=excluded.geometry_source,
      geometry_source_url=excluded.geometry_source_url,official=true;
    update public.hiking_routes
      set trace_available=true,published=true,
        official_url=v_source->>'page_url',
        distance_km=coalesce(distance_km,(v_source->>'official_km')::numeric)
      where id=v_id;
  end loop;
end
